const MIN_WINDOW_LINES = 1;
const MAX_WINDOW_LINES = 50;
const MAX_OUTPUT_LENGTH = 30000;

// Ace highlight parameters.
const ACE_HIGHLIGHT = {
    'class': 'ace_highlight_code',
    'lang': 'python3',
    'ace-lang': '',
    'font-size': '11pt',
    'start-line-number': null,
    'min-lines': MIN_WINDOW_LINES,
    'max-lines': MAX_WINDOW_LINES,
    'readonly': true,
    'dark-theme-mode': null
};

// Ace interactive parameters.
const ACE_INTERACTIVE = {
    'class': 'ace_interactive_code',
    'lang': 'python3',
    'ace-lang': '',
    'font-size': '11pt',
    'hidden': false,
    'start-line-number': 1,
    'button-name': 'Try it!',
    'readonly': null,
    'stdin': '',
    'stdin-taid': '',
    'file-taids': {},
    'file-upload-id': null,
    'prefix': '',
    'suffix': '',
    'params': '{"cputime": 5}',
    'code-mapper': null,
    'html-output': null,
    'min-lines': MIN_WINDOW_LINES,
    'max-lines': MAX_WINDOW_LINES,
    'max-output-length': MAX_OUTPUT_LENGTH,
    'dark-theme-mode': null
};

// Language names that Jobe knows under a different name than the one authors habitually write
// (and that Markdown renderers habitually emit).
const JOBE_LANG_ALIASES = {
    'python': 'python3'
};

/**
 * Normalise a language name into one Jobe and Ace will recognise: strip the "language-" prefix
 * that TinyMCE's Prism filter and most Markdown renderers put on the class, then map any known
 * alias. Applied on both the explicit-attribute and simplified-class-mode paths, so the two
 * agree on what a bare "python" fence or class="language-python" means.
 * @param {string} lang The raw language name, as authored.
 * @return {string} The normalised language name.
 */
const normaliseLang = (lang) => {
    const stripped = String(lang).replace(/^language-/, '');
    return JOBE_LANG_ALIASES.hasOwnProperty(stripped) ? JOBE_LANG_ALIASES[stripped] : stripped;
};

const popItemPair = (alist, element) => {
  const index = alist.indexOf(element);
  if (index !== -1) {
      const pair = alist[index + 1] || null;
      alist.splice(index, 2);
      return [element, pair];
  }
  return null;
};


export class UiParameters {
    constructor(pre) {
        this.pre = pre;
        this.paramsMap = {};
        this.modifiedLang = false;
        this.execLang = null;
        this.stdin = '';
        this.files = null;
        this.htmlOutput = null;
        this.sandboxParams = [];
    }

    /**
     * Extract from the given DOM pre element its various attributes.
     * @param {boolean} isInteractive True if is interactive, else false.
     * @param {array} config Config for buttons and darkmode.
     */
    extractUiParameters(isInteractive, config) {
        // Adds defaults. Cloned so per-block overrides below (button-name, and the
        // extractSimplifiedClassModeParameters equivalents for lang/start-line-number) never
        // mutate the shared ACE_HIGHLIGHT/ACE_INTERACTIVE constants and leak into later blocks on
        // the same page.
        const defaultParams = {...(isInteractive ? ACE_INTERACTIVE : ACE_HIGHLIGHT)};
        if (isInteractive) {
            defaultParams['button-name'] = config.button_label;
        }
        for (const attrName in defaultParams) {
            if (defaultParams.hasOwnProperty(attrName)) {
                let value = '';
                let dataName = '';
                let attr = this.pre.attributes.getNamedItem(attrName);
                if (attr) {
                    dataName = attrName;
                } else { // Try data- as a prefix if 'raw' access fails.
                    dataName = 'data-' + attrName;
                    attr = this.pre.attributes.getNamedItem(dataName);
                }
                if (attr) {
                    value = attr.value;
                    switch (attrName) {
                        case 'start-line-number':
                            value = value.toLowerCase() === 'none' ? null : parseInt(value);
                            break;
                        case 'min-lines':
                        case 'max-lines':
                            value = parseInt(value);
                            break;
                        case 'hidden':
                            value = true; // If the 'hidden' attribute exists, it's True!
                            break;
                        case 'lang':
                            this.modifiedLang = true; // Keeps track of modifications, so no overrides.
                            break;
                        default:
                            break;
                    }
                } else {
                value = defaultParams[attrName];
                }
            this.paramsMap[attrName] = value;
            }
        }

        // Sets dark theme according to config if not previously set.
        if (this.paramsMap['dark-theme-mode'] === null) {
            this.paramsMap['dark-theme-mode'] = config.dark_theme_mode; // 0, 1, 2 for never, sometimes, always
        }
        // Extracts the Tiny Parameters out.
        this.extractTinyParams();
    }

    /**
     * Extract from the the class specifier (options) various attributes.
     * @param {boolean} isInteractive True if is interactive, else false.
     * @param {array} config Config for buttons and darkmode.
     * @param {array} options comes form the class specifier string.
     */
    extractSimplifiedClassModeParameters(isInteractive, config, options) {
        const language = options.shift();
        const lineNumbering = popItemPair(options, 'line-numbers') || popItemPair(options, 'start-line-number');
        // Cloned for the same reason as in extractUiParameters(): these per-block overrides must
        // never mutate the shared ACE_HIGHLIGHT/ACE_INTERACTIVE constants.
        const defaultParams = {...(isInteractive ? ACE_INTERACTIVE : ACE_HIGHLIGHT)};

        defaultParams.lang = language;
        this.modifiedLang = true;
        if (isInteractive) {
            defaultParams['button-name'] = config.button_label;
        }
        if (lineNumbering !== null) {
            defaultParams['start-line-number'] = parseInt(lineNumbering[1]) || 1;
        }

        for (const attrName in defaultParams) {
            const valuePair = popItemPair(options, attrName);
            const value = (valuePair !== null) ? valuePair[1] : defaultParams[attrName];
            this.paramsMap[attrName] = value;
        }

        // Normalised after the loop rather than before it, because 'lang' is itself one of the
        // keys above: an explicit "python:interactive:lang:python" pair would otherwise overwrite
        // an already-normalised value and slip past unmapped.
        this.paramsMap.lang = normaliseLang(this.paramsMap.lang);

        // Sets dark theme according to config if not previously set (mirrors extractUiParameters()).
        if (this.paramsMap['dark-theme-mode'] === null) {
            this.paramsMap['dark-theme-mode'] = config.dark_theme_mode; // 0, 1, 2 for never, sometimes, always.
        }
    }

    /**
     * Extract the language from the TinyMCE code editor.
     */
    extractTinyParams() {
        // Takes the data-lang from the class if edited using Prism TinyMCE editor filter.
        const splitClass = this.paramsMap.class.split(" ");
        // Left open so can deal with more attributes if desired.
        splitClass.forEach((attribute) => {
            if (attribute.startsWith('language') && this.modifiedLang === false) {
                this.paramsMap.lang = attribute;
            }
        });
        this.paramsMap.lang = normaliseLang(this.paramsMap.lang);
    }

    /**
     * Sets the uiParameter of stdin 'stdin-taid' which should be the id of an element.
     */
    setStdin() {
        const taid = this.paramsMap['stdin-taid'];
        const stdin = this.paramsMap.stdin;
        if (taid) {
            const box = document.querySelector('#' + taid);
            // Handles invalid textarea names.
            if (box === null) {
                this.stdin = null;
            } else {
                this.stdin = box.value;
            }
        } else if (stdin) {
            this.stdin = stdin;
        } else {
            this.stdin = '';
        }
    }

    /**
     * Sets the uiParameter of files.
     *
     * @param {type} files The files to be processed.
     */
    setFiles(files) {
        this.files = files;
    }

    /**
     * Sets the execution language.
     *
     * @param {type} lang The coding language to be used.
     */
    setExecLang(lang) {
        this.execLang = lang;
    }

    /**
     * Sets HTML output.
     *
     * @param {type} hasHtml If not null, there is Html output.
     */
    setHtmlOutput(hasHtml) {
        this.htmlOutput = hasHtml;
    }

    /**
     * Sets the uiParams' params Array to all files.
     *
     * @param {Array} paramsArray An array of all the filenames used.
     */
    setSandboxParams(paramsArray) {
        this.sandboxParams = paramsArray;
    }

    /**
     * Sets run-params in the paramsMap to be executed on run.
     *
     * @param {String} paramsString A JSON-compliant params string.
     */
    setRunParams(paramsString) {
        this.paramsMap['run-params'] = paramsString;
    }
}
